CREATE FUNCTION public.save_customer(p jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid:=(p->>'id')::uuid; cname text:=nullif(trim(p->>'name'),''); cphone text:=nullif(trim(p->>'phone'),''); BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin only'; END IF; IF cname IS NULL OR cphone IS NULL THEN RAISE EXCEPTION 'Enter a customer name and phone'; END IF; INSERT INTO public.customers(id,name,phone) VALUES(coalesce(cid,gen_random_uuid()),cname,cphone) ON CONFLICT(id) DO UPDATE SET name=excluded.name,phone=excluded.phone RETURNING id INTO cid; RETURN cid; END $$; REVOKE ALL ON FUNCTION public.save_customer(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_customer(jsonb) TO authenticated,service_role;